"""Actual page-10 image reading, exact annual cash-flow columns; Q4 cover retained."""
import datetime,hashlib,json,pathlib,runpy
B=pathlib.Path('data/initialization-08b-remediation-work')
BODY='707a36cbbc34429142fff4cb9d9c7622f9ad0af6526e73fec4232d678faf23f6'
ROWS=[('CFO','2.844.926.626.303','1.342.697.872.512','Lưu chuyển tiền thuần từ hoạt động kinh doanh','20'),('CFI_SUPPORTING','(577.951.029.840)','(538.638.730.002)','Lưu chuyển tiền thuần từ hoạt động đầu tư','30'),('CASH_CAPEX_REPORTED','(760.621.091.924)','(802.275.672.956)','Tiền chi để mua sắm, xây dựng TSCĐ và các tài sản dài hạn khác','21')]
def validate(c,p,R):
 row=next((r for r in ROWS if r[0]==c.get('itemId')),None);d=c.get('sourceImageColumnDefinition',{})
 if not row or (c['itemId'],c['lexicalValue'],d.get('comparativeLexical'),c['sourceCaption'],c['sourceRowCode'])!=row:return False
 text=R['compact'](R['full_text'](p,'passA'));near=' '.join(w['text'] for w in p['passA'] if w['x']<.53 and abs(w['y']+w['height']/2-c['rowY'])<.025)
 code=any(w['text'].split()[0]==c['sourceRowCode'] and .1<w['x']<.16 and abs(w['y']+w['height']/2-c['rowY'])<.025 for w in p['passA'])
 return (c['bodyHash']==BODY and c['page']==10 and c['ticker']=='GVR' and c['scope']=='CONSOLIDATED' and c['unit']=='CURRENCY' and c['currency']=='VND' and c['periodType']=='ANNUAL' and c['period']['start']=='2023-01-01' and c['period']['end']=='2023-12-31' and d.get('currentColumnOrdinal')==0 and d.get('currentLexical')==c['lexicalValue'] and .60<c['columnX']<.77 and code and R['compact'](c['sourceCaption']) in R['compact'](near)
 and all(R['compact'](s) in text for s in ['hợp nhất','Đơn vị tính: VND','01/01/2023','31/12/2023','01/01/2022','31/12/2022'])
 and sum(w['text']==c['lexicalValue'] and w['confidence']>=.8 and abs(w['x']-c['columnX'])<.001 and abs(w['y']+w['height']/2-c['rowY'])<.001 for w in p['passA'])==1
 and sum(w['text']==d['comparativeLexical'] and w['x']>.8 and abs(w['y']+w['height']/2-c['rowY'])<.02 for w in p['passA'])==1)
def main():
 R=runpy.run_path('scripts/reconcile-08b-extraction.py');sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();f=B/'ocr'/f'{BODY}-p10.json';p=json.loads(f.read_text());q=next(q for q in json.loads((B/'qualifications.json').read_text()) if q['bodyHash']==BODY);assert q['period']['end']=='2023-12-31' and sha(f.with_suffix('.png'))==p['renderSha256'];cells=[]
 for item,lex,prior,caption,code in ROWS:
  w=next(w for w in p['passA'] if w['text']==lex);d={'layout':'GVR_EXACT_ANNUAL_CF_IMAGE','currentColumnOrdinal':0,'currentLexical':lex,'comparativeLexical':prior};c={'ticker':'GVR','securityId':q['securityId'],'documentId':q['documentId'],'bodyHash':BODY,'page':10,'itemId':item,'sourceCaption':caption,'captionAlternative':R['fold'](caption),'sourceRowCode':code,'lexicalValue':lex,'verificationLexicalValue':lex,'verifiedCanonicalInteger':R['numeric_value'](lex),'unit':'CURRENCY','currency':'VND','scope':'CONSOLIDATED','period':q['period'],'periodType':'ANNUAL','columnX':w['x'],'rowY':w['y']+w['height']/2,'extractionMethod':p['engineA'],'verificationMethod':'CODEX_ASSISTANT_SOURCE_IMAGE_READING','renderSha256':p['renderSha256'],'sourceImageColumnDefinition':d,'status':'VERIFIED_TRANSCRIPTION_REVIEW_CANDIDATE','comparativeColumn':False,'independentHumanApproval':None,'sourceOcrProofFile':str(f)};assert validate(c,p,R),item;cells.append(c)
 proof=B/'gvr-annual-cashflow-source-image-reader-proof.json';proof.write_text(json.dumps({'method':'CODEX_ASSISTANT_SOURCE_IMAGE_READING','recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'governanceStatus':'REVIEW_CANDIDATE','independentHumanApproval':None,'rows':[{**c,'periodStart':c['period']['start'],'periodEnd':c['period']['end'],'currentLexical':c['lexicalValue'],'rowCode':c['sourceRowCode'],'caption':c['sourceCaption']} for c in cells],'sourceRisk':'Q4 unreviewed report explicitly prints annual cash-flow date ranges. No audited status, normalized CAPEX, or quarterly-to-annual extrapolation inferred.'},ensure_ascii=False,indent=2)+'\n')
 for c in cells:c.update(sourceImageProofFile=str(proof),sourcePageEvidenceHashes=[sha(f),sha(proof)])
 out=B/'source-image-verified-cells.json';old=json.loads(out.read_text());items={r[0] for r in ROWS};old=[c for c in old if not(c['bodyHash']==BODY and c['itemId'] in items)]+cells;out.write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n');print({'newCells':len(cells)})
if __name__=='__main__':main()
